    "faqs": [
      {
        "question": "What is the primary advantage of Mesh topology in police and military communications?",
        "answer": "Fault tolerance and high redundancy. If one link fails, traffic is automatically rerouted through alternate paths without disruption."
      },
      {
        "question": "What device is used at both ends of a Bus topology to prevent signal reflection?",
        "answer": "A Terminator (typically 50-ohm resistor for coaxial cables) absorbs the signal when it reaches the end of the cable."
      },
      {
        "question": "Which topology is most commonly implemented in modern enterprise local area networks?",
        "answer": "Star topology using twisted-pair Ethernet cables (Cat6) connected to central Layer-2/Layer-3 managed switches."
      }
    ]
